using DriveOS.Modules.Workforce.Domain.EmployeeDocuments;using DriveOS.SharedKernel.Identifiers;using Microsoft.EntityFrameworkCore;
namespace DriveOS.Modules.Workforce.Infrastructure.Persistence.Repositories;
internal sealed class EmployeeDocumentRepository(WorkforceDbContext db):IEmployeeDocumentRepository{public Task<EmployeeDocument?> GetAsync(OrganizationId org,EmployeeDocumentId id,bool tracking,CancellationToken ct=default){IQueryable<EmployeeDocument>q=db.EmployeeDocuments;if(!tracking)q=q.AsNoTracking();return q.SingleOrDefaultAsync(x=>x.OrganizationId==org&&x.Id==id,ct);}public async Task<IReadOnlyList<EmployeeDocument>> ListAsync(OrganizationId org,EmployeeId? employee,EmployeeDocumentCategory? category,EmployeeDocumentStatus? status,CancellationToken ct=default){var q=db.EmployeeDocuments.AsNoTracking().Where(x=>x.OrganizationId==org);if(employee.HasValue)q=q.Where(x=>x.EmployeeId==employee.Value);if(category.HasValue)q=q.Where(x=>x.Category==category.Value);if(status.HasValue)q=q.Where(x=>x.Status==status.Value);return await q.OrderByDescending(x=>x.CreatedAtUtc).ToListAsync(ct);}public Task<bool> DocumentReferenceExistsAsync(OrganizationId org,Guid reference,EmployeeDocumentId? excluding,CancellationToken ct=default)=>db.EmployeeDocuments.AsNoTracking().AnyAsync(x=>x.OrganizationId==org&&x.DocumentReferenceId==reference&&(!excluding.HasValue||x.Id!=excluding.Value),ct);public void Add(EmployeeDocument x)=>db.EmployeeDocuments.Add(x);}
